  ```json
  {
    /*
    include 指定需要编译的文件
    **  表示任意文件夹
    *   表示任意文件

    exclude 指定不需要编译的文件
    默认值['node_modules','bower_components','jspm_packages']

    extends 基础config目录下的base.json文件中的配置信息到tsconfig.json
    */
    "include": [
      "./src/**/*"
    ],
    "exclude": [
      "./src/**/*"
    ],
    "extends": "./config/base",
    // 编译器配置
    "compilerOptions": {

      // 用来指定TS文件被编译的版本，默认转为ES3
      "target": "ES6",

      // 指定要使用的模块化标准 ES2015 = ES6
      "module": "ES6",

      // 用来指定项目中要使用的库
  	// "lib": [],

      // 指定编译后的文件所在的目录
      "outDir": "./dist",

      // 将代码合并为一个文件,设置outFile后
      // 会将全局作用域中的代码合并到同一个文件中
      // module 必须设置为system或amd才能把模块化的代码合并
      "outFile": "./dist/app.js",

      // 是否对js文件进行编译，默认是false
      "allowJs": false,

      // 检查js代码是否符合TS规范
      "checkJs": false,

      // 是否移除注释，默认为false保留注释
      "removeComments": false,

      // 不生成编译后的文件
      "noEmit": true,

      //当有错误时不生成文件,默认false
      "noEmitOnError": true,

      // 所有严格检查的总开关，为true时以下都不用写了
      "strict": false,

      // 用来设置编译后的文件是否使用严格模式, 默认为false
      // 严格模式编译的代码好一些， 当有模块时会自动进入严格模式
      "alwaysStrict": false,

