    const hello = Vue.extend({
        template:`<h2>{{msg}}</h2>`,
        data(){
            return{
                msg:"简单"
            }
        }
    })

    //创建app组件，管理其它全部组件(一人之下，万人之上)
    const app =Vue.extend({
        components:{
            school,
            hello
        },
        template:`<div>
        <school></school>
        <hello></hello>
        </div>`
    })

    //创建vm管理app组件
    new Vue({
        el:"#root",
        template:`<app></app>`,
        components:{
            app
        }
    })
</script>
