import axios from "axios";

const getList = {
    namespaced: true,    //开启命名空间
    actions: {
        jia(context) {
            axios.get('http://192.168.2.110:4523/m1/1074324-0-default/server').then(data => {
                console.log(data)
                context.commit('JIA', data.data)
